import type { Metadata } from "next";

export const siteOrigin = "https://press-say.app";

type Locale = "fr" | "en";

// A page-level openGraph object replaces the root one wholesale, so the image
// generated by app/opengraph-image.tsx must be restated here.
const shareImage = (locale: Locale) => ({
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt:
    locale === "fr"
      ? "Pressay — la dictée locale pour Mac"
      : "Pressay — local dictation for Mac",
});

/**
 * hreflang targets: the language alone, so every French- or English-speaking
 * region is covered (not only fr-FR / en-US). French is the x-default.
 */
export function languageAlternates(path: string, origin = ""): Record<string, string> {
  return {
    fr: `${origin}/fr${path}`,
    en: `${origin}/en${path}`,
    "x-default": `${origin}/fr${path}`,
  };
}

export const defaults: Record<Locale, { title: string; description: string }> = {
  fr: {
    title: "Pressay — Le Voice OS local du Mac",
    description:
      "Dictez, transformez et corrigez dans chaque app avec une route de traitement visible et le local par défaut.",
  },
  en: {
    title: "Pressay — The local Voice OS for Mac",
    description:
      "Dictate, rewrite and correct in every app, with a visible processing route and local by default.",
  },
};

/**
 * Per-locale metadata for a public page: its own canonical URL, fr/en
 * alternates (hreflang) and OpenGraph tags in the page language.
 * `path` is the locale-less path, e.g. "" for home or "/pricing".
 */
export function localizedMetadata({
  locale,
  path,
  title,
  description,
  index = true,
}: {
  locale: Locale;
  path: string;
  title?: string;
  description?: string;
  index?: boolean;
}): Metadata {
  const url = `/${locale}${path}`;
  const fallback = defaults[locale];
  const pageDescription = description ?? fallback.description;
  const ogTitle = title ? `${title} · Pressay` : fallback.title;
  return {
    ...(title ? { title } : { title: { absolute: fallback.title } }),
    description: pageDescription,
    alternates: {
      canonical: url,
      languages: languageAlternates(path),
    },
    openGraph: {
      type: "website",
      siteName: "Pressay",
      locale: locale === "fr" ? "fr_FR" : "en_US",
      alternateLocale: locale === "fr" ? ["en_US"] : ["fr_FR"],
      url: `${siteOrigin}${url}`,
      title: ogTitle,
      description: pageDescription,
      images: [shareImage(locale)],
    },
    twitter: {
      card: "summary_large_image",
      title: ogTitle,
      description: pageDescription,
      images: [shareImage(locale)],
    },
    ...(index ? {} : { robots: { index: false, follow: false } }),
  };
}

/** Private or transactional pages: never indexed, no canonical claim. */
export const privateMetadata: Metadata = {
  robots: { index: false, follow: false },
};
